"use client"

import * as React from "react"
import { createPortal } from "react-dom"
import { X } from "lucide-react"

import {
  useControllableState,
  useIsClient,
  useIsomorphicLayoutEffect,
} from "../hooks"
import { useFocusTrap } from "../lib/df-focus-trap"
import { useDfStrings } from "../lib/df-intl"
import { cn, composeEventHandlers } from "../lib/utils"
import { Button } from "./df-button"
import { ScrollArea } from "./df-scroll-area"

type DrawerSide = "right" | "bottom"
type DrawerSize = "sm" | "md" | "lg"

type DrawerContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
  triggerRef: React.RefObject<HTMLElement | null>
  titleId: string
  descriptionId: string
  hasDescription: boolean
  setHasDescription: (value: boolean) => void
  side: DrawerSide
  size: DrawerSize
}

const DrawerContext = React.createContext<DrawerContextValue | null>(null)

function useDrawerContext() {
  const ctx = React.useContext(DrawerContext)
  if (!ctx) throw new Error("Drawer components must be used within Drawer")
  return ctx
}

function Drawer({
  open,
  defaultOpen = false,
  onOpenChange,
  side = "right",
  size = "md",
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  side?: DrawerSide
  size?: DrawerSize
  children: React.ReactNode
}) {
  const [isOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const triggerRef = React.useRef<HTMLElement | null>(null)
  const titleId = React.useId()
  const descriptionId = React.useId()
  const [hasDescription, setHasDescription] = React.useState(false)

  return (
    <DrawerContext.Provider
      value={{
        open: isOpen,
        setOpen,
        triggerRef,
        titleId,
        descriptionId,
        hasDescription,
        setHasDescription,
        side,
        size,
      }}
    >
      {children}
    </DrawerContext.Provider>
  )
}

function DrawerTrigger({
  children,
  render,
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement> & {
  render?: React.ReactElement
}) {
  const { open, setOpen, triggerRef } = useDrawerContext()

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    if (render) {
      const renderOnClick = (
        render.props as {
          onClick?: (event: React.MouseEvent<HTMLElement>) => void
        }
      ).onClick
      renderOnClick?.(event)
      if (event.defaultPrevented) return
    }
    composeEventHandlers(props.onClick, () => {
      setOpen(true)
    })(event as React.MouseEvent<HTMLButtonElement>)
  }

  if (render) {
    return React.cloneElement(render, {
      ...props,
      ref: triggerRef as React.Ref<HTMLButtonElement>,
      "data-df-drawer-trigger": "",
      "aria-expanded": open,
      "aria-haspopup": "dialog",
      onClick: handleClick,
      className: cn(
        className,
        (render.props as { className?: string }).className
      ),
      children:
        children ??
        (render.props as { children?: React.ReactNode }).children,
    } as never)
  }

  return (
    <button
      type="button"
      data-df="drawer-trigger"
      {...props}
      ref={triggerRef as React.Ref<HTMLButtonElement>}
      data-df-drawer-trigger=""
      aria-expanded={open}
      aria-haspopup="dialog"
      className={cn(className)}
      onClick={handleClick}
    >
      {children}
    </button>
  )
}

function DrawerContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  const {
    open,
    setOpen,
    triggerRef,
    titleId,
    descriptionId,
    hasDescription,
    side,
    size,
  } = useDrawerContext()
  const panelRef = React.useRef<HTMLDivElement | null>(null)
  const mounted = useIsClient()

  useFocusTrap({
    open,
    panelRef,
    triggerRef,
    onEscape: () => setOpen(false),
  })

  if (!mounted || !open) return null

  return createPortal(
    <div data-df="drawer-root" data-side={side}>
      <div
        data-df="drawer-scrim"
        aria-hidden
        onClick={() => setOpen(false)}
      />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={hasDescription ? descriptionId : undefined}
        data-df="drawer-content"
        data-side={side}
        data-size={size}
        tabIndex={-1}
        className={cn(className)}
        {...props}
      >
        {children}
      </div>
    </div>,
    document.body
  )
}

function DrawerHeader({
  className,
  children,
  showClose = true,
  ...props
}: React.ComponentProps<"div"> & {
  showClose?: boolean
}) {
  const s = useDfStrings()
  return (
    <div data-df="drawer-header" className={cn(className)} {...props}>
      <div data-df="drawer-header-copy">{children}</div>
      {showClose ? (
        <DrawerClose
          render={
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label={s.drawerClose}
            >
              <X className="size-4" />
            </Button>
          }
        />
      ) : null}
    </div>
  )
}

function DrawerTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDrawerContext()
  return (
    <h2
      id={titleId}
      data-df="drawer-title"
      className={cn(className)}
      {...props}
    />
  )
}

function DrawerDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  const { descriptionId, setHasDescription } = useDrawerContext()

  useIsomorphicLayoutEffect(() => {
    setHasDescription(true)
    return () => setHasDescription(false)
  }, [setHasDescription])

  return (
    <p
      id={descriptionId}
      data-df="drawer-description"
      className={cn(className)}
      {...props}
    />
  )
}

function DrawerBody({
  className,
  children,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div data-df="drawer-body" className={cn(className)} {...props}>
      <ScrollArea visibility="hover">{children}</ScrollArea>
    </div>
  )
}

function DrawerFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-df="drawer-footer" className={cn(className)} {...props} />
  )
}

function DrawerClose({
  children,
  render,
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement> & {
  render?: React.ReactElement
}) {
  const { setOpen } = useDrawerContext()

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    if (render) {
      const renderOnClick = (
        render.props as {
          onClick?: (event: React.MouseEvent<HTMLElement>) => void
        }
      ).onClick
      renderOnClick?.(event)
      if (event.defaultPrevented) return
    }
    composeEventHandlers(props.onClick, () => {
      setOpen(false)
    })(event as React.MouseEvent<HTMLButtonElement>)
  }

  if (render) {
    return React.cloneElement(render, {
      ...props,
      "data-df-drawer-close": "",
      onClick: handleClick,
      className: cn(
        className,
        (render.props as { className?: string }).className
      ),
      children:
        children ??
        (render.props as { children?: React.ReactNode }).children,
    } as never)
  }

  return (
    <button
      type="button"
      data-df="drawer-close"
      {...props}
      className={cn(className)}
      onClick={handleClick}
    >
      {children}
    </button>
  )
}

export {
  Drawer,
  DrawerBody,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
}
export type { DrawerSide, DrawerSize }

/** CSS selector for tabbable controls inside a modal panel. */
export const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "textarea:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",")

export type FocusTrapKeyAction =
  | "close"
  | "focus-panel"
  | "focus-last"
  | "focus-first"
  | "none"

export type FocusTrapKeyDecision = {
  action: FocusTrapKeyAction
  preventDefault: boolean
}

/**
 * Decide how a keydown should affect a modal focus trap.
 * Escape closes. Tab cycles only when focus is on an edge item.
 */
export function resolveFocusTrapKey(options: {
  key: string
  shiftKey: boolean
  focusableCount: number
  activeIsFirst: boolean
  activeIsLast: boolean
}): FocusTrapKeyDecision {
  if (options.key === "Escape") {
    return { action: "close", preventDefault: true }
  }
  if (options.key !== "Tab") {
    return { action: "none", preventDefault: false }
  }
  if (options.focusableCount === 0) {
    return { action: "focus-panel", preventDefault: true }
  }
  if (options.shiftKey && options.activeIsFirst) {
    return { action: "focus-last", preventDefault: true }
  }
  if (!options.shiftKey && options.activeIsLast) {
    return { action: "focus-first", preventDefault: true }
  }
  return { action: "none", preventDefault: false }
}

/** Prefer the trigger, then the focus captured when the layer opened. */
export function resolveFocusRestoreTarget<T>(
  trigger: T | null | undefined,
  previous: T | null | undefined
): T | null {
  return trigger ?? previous ?? null
}

/** First tabbable control, or the panel itself when the panel has none. */
export function resolveInitialFocus<T>(
  focusables: readonly T[],
  panel: T | null | undefined
): T | null {
  return focusables[0] ?? panel ?? null
}

/** Move focus without scrolling ancestor overflow containers. */
export function focusWithoutScroll(
  element: HTMLElement | null | undefined
): void {
  element?.focus({ preventScroll: true })
}

export type OverflowStyleHost = {
  style: { overflow: string }
}

/** Lock page scroll and return the prior overflow value for restore. */
export function lockBodyScroll(body: OverflowStyleHost): string {
  const previous = body.style.overflow
  body.style.overflow = "hidden"
  return previous
}

/** Restore page scroll from a value returned by lockBodyScroll. */
export function unlockBodyScroll(
  body: OverflowStyleHost,
  previousOverflow: string
): void {
  body.style.overflow = previousOverflow
}

import { useEffect, useRef, type RefObject } from "react"

import {
  FOCUSABLE_SELECTOR,
  focusWithoutScroll,
  lockBodyScroll,
  resolveFocusRestoreTarget,
  resolveFocusTrapKey,
  resolveInitialFocus,
  unlockBodyScroll,
} from "./trap"

type UseFocusTrapOptions = {
  open: boolean
  panelRef: RefObject<HTMLElement | null>
  triggerRef: RefObject<HTMLElement | null>
  onEscape: () => void
}

/**
 * Modal focus lifecycle: capture prior focus, lock scroll, move focus into
 * the panel, trap Tab, close on Escape, and restore focus on close.
 */
export function useFocusTrap({
  open,
  panelRef,
  triggerRef,
  onEscape,
}: UseFocusTrapOptions) {
  const previousFocusRef = useRef<HTMLElement | null>(null)
  const wasOpenRef = useRef(false)
  const onEscapeRef = useRef(onEscape)

  useEffect(() => {
    onEscapeRef.current = onEscape
  }, [onEscape])

  useEffect(() => {
    if (!open) {
      if (wasOpenRef.current) {
        wasOpenRef.current = false
        const restore = resolveFocusRestoreTarget(
          triggerRef.current,
          previousFocusRef.current
        )
        previousFocusRef.current = null
        focusWithoutScroll(restore)
      }
      return
    }

    wasOpenRef.current = true
    const active = document.activeElement
    previousFocusRef.current =
      active instanceof HTMLElement ? active : null

    const previousOverflow = lockBodyScroll(document.body)
    const panel = panelRef.current
    const focusables = panel
      ? Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR))
      : []
    const initial = resolveInitialFocus(focusables, panel)
    focusWithoutScroll(initial)

    return () => {
      unlockBodyScroll(document.body, previousOverflow)
    }
  }, [open, panelRef, triggerRef])

  useEffect(() => {
    if (!open) return

    const onKeyDown = (event: KeyboardEvent) => {
      const panel = panelRef.current
      const focusables = panel
        ? Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR))
        : []
      const decision = resolveFocusTrapKey({
        key: event.key,
        shiftKey: event.shiftKey,
        focusableCount: focusables.length,
        activeIsFirst: document.activeElement === focusables[0],
        activeIsLast:
          document.activeElement === focusables[focusables.length - 1],
      })

      if (decision.action === "none") return
      if (decision.preventDefault) event.preventDefault()

      if (decision.action === "close") {
        onEscapeRef.current()
        return
      }
      if (decision.action === "focus-panel") {
        focusWithoutScroll(panel)
        return
      }
      if (decision.action === "focus-last") {
        focusWithoutScroll(focusables[focusables.length - 1])
        return
      }
      if (decision.action === "focus-first") {
        focusWithoutScroll(focusables[0])
      }
    }

    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [open, panelRef])
}
